import os
import sys

print("CWD:", os.getcwd())
print("\nWorkspace files:")
for name in sorted(os.listdir(".")):
    print("  ", name, os.path.getsize(name) if os.path.isfile(name) else "<dir>")

skill_dir = ".codex/skills/pdf"
print("\nSkill directory:", skill_dir)
if os.path.isdir(skill_dir):
    for root, dirs, files in os.walk(skill_dir):
        for f in sorted(files):
            print("  ", os.path.join(root, f))
else:
    print("  (not found)")

print("\nLibrary availability:")
for lib in ["pypdf", "reportlab", "pdfplumber"]:
    try:
        mod = __import__(lib)
        print(f"  {lib}: OK ({getattr(mod, '__version__', 'unknown')})")
    except Exception as e:
        print(f"  {lib}: MISSING ({e})")
